const missing = REFS.filter(([k]) => { const m = k.match(/^(.+?)\s(\d{4}[ab]?)$/); const name = m[1]; const yr = m[2];
  const alt = name.replace(' et al.', ' et al.'); return !(new RegExp(alt.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\s?\\(?' + yr).test(bodySrc)); });
