const yearCites = [...bodySrc.matchAll(/([A-ZÁÉÍÓÚÑvd][\wáéíóúñü'-]+(?:\s(?:et al\.|and\s[A-ZÁÉÍÓÚ][\wáéíóúñü-]+)|\sder\sEnt(?:\set\sal\.)?|\sScientific\sCommittee|\sCore\sTeam)?)\s\(?((?:19|20)\d{2}[ab]?)\)?/g)].map(m => m[1] + ' ' + m[2]);
